// ── Aidapt ALMS · Build Leave Approval-Request Email Payload ──────────
// n8n Code node · Mode: "Run Once for Each Item"
// Event: leave.approval_request.
//   stage "manager" → the employee's manager, with Approve and Reject in the email.
//   stage "final"   → Hitesh, with the same buttons, only after the manager approves.
// The buttons use the backend decision links, so the choice is recorded from the email.

const body = $json.body ?? $json;
const src  = body.data ?? $json.data ?? $json;

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const stage        = src.stage === 'final' ? 'final' : 'manager';
const isFinal      = stage === 'final';
const employeeName = esc(src.employeeName || 'An employee');
const leaveType    = esc(src.leaveType || 'Leave');
const managerName  = esc(src.managerName || 'their manager');
const finalName    = esc(src.finalApproverName || 'the final approver');
const days         = Number(src.days) || 0;
const daysLabel    = `${days} ${days === 1 ? 'day' : 'days'}`;

const evidenceRaw = typeof src.evidenceUrl === 'string' ? src.evidenceUrl.trim() : '';
const evidenceRow = evidenceRaw
  ? '<tr>'
    + '<td style="padding:14px 18px;font-family:Arial,Helvetica,sans-serif;font-size:13px;color:#785d5c;vertical-align:top;">Prescription</td>'
    + '<td style="padding:14px 18px;font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:600;color:#2e1f1f;">'
    + '<a href="' + esc(evidenceRaw) + '" style="color:#11A8A0;text-decoration:underline;">View doctor\'s prescription</a>'
    + '</td></tr>'
  : '';

const payload = {
  requestId:  esc(src.requestId),
  stage,
  employeeName,
  leaveType,
  fromDate:   esc(src.fromDate),
  toDate:     esc(src.toDate),
  days,
  daysLabel,
  reason:     esc(src.reason) || 'No reason given',
  evidenceUrl: evidenceRaw,
  evidenceRow,
  approveUrl: typeof src.approveUrl === 'string' ? src.approveUrl : '',
  rejectUrl:  typeof src.rejectUrl === 'string' ? src.rejectUrl : '',
  eyebrow:  isFinal ? 'Final approval needed' : 'A request is waiting on your approval',
  headline: isFinal
    ? `${employeeName}'s ${leaveType} leave needs your final approval`
    : `${employeeName} requested ${leaveType} leave`,
  stepNote: isFinal
    ? `Approved by ${managerName}. Approving deducts ${daysLabel} from their ${leaveType} leave.`
    : `If you approve, it goes to ${finalName} for final approval. Their balance does not change yet.`,
  approveLabel: isFinal ? 'Give final approval' : 'Approve',
  tag:          isFinal ? 'Final Approval' : 'Leave Request',
};

payload.to      = body.to ?? src.approverEmail ?? '';
payload.subject = body.subject ?? (isFinal
  ? `Final approval needed: ${src.employeeName}'s ${src.leaveType} leave`
  : `Leave request from ${src.employeeName} (${src.leaveType})`);

if (!payload.to) {
  throw new Error(`leave.approval_request ${src.requestId}: missing recipient`);
}
if (!payload.approveUrl || !payload.rejectUrl) {
  throw new Error(`leave.approval_request ${src.requestId}: approve/reject URL missing`);
}

return { json: payload };

// ── Aidapt ALMS · Build Regularization-Request Email Payload ──────────
// n8n Code node · Mode: "Run Once for Each Item"

const PROD_BASE = 'https://aidapt-alms-backend.onrender.com';
const DEV_BASE  = 'http://localhost:4000';

const body = $json.body ?? $json;
const src  = body.data ?? $json.data ?? $json;

const fixUrl = (url) =>
  typeof url === 'string' ? url.replace(DEV_BASE, PROD_BASE) : '';

const payload = {
  requestId:            src.requestId            ?? '',
  employeeName:         src.employeeName          ?? 'Unknown',
  employeeEmail:        src.employeeEmail         ?? '',
  managerEmail:         src.managerEmail          ?? '',
  date:                 src.date                  ?? '',
  requestedCheckInPkt:  src.requestedCheckInPkt   ?? '—',
  requestedCheckOutPkt: src.requestedCheckOutPkt  ?? '—',
  reason:               src.reason                ?? '—',
  reviewUrl:            fixUrl(src.reviewUrl),
};

payload.subject = body.subject
  ?? `Regularization request from ${payload.employeeName} (${payload.date})`;
payload.to      = body.to ?? payload.managerEmail;

return { json: payload };

// ── Aidapt ALMS · Build Leave-Decision Email Payload ──────────────────
// n8n Code node · Mode: "Run Once for Each Item"
// Event: leave.decision. Goes to the employee who applied, not to Hitesh.
// stage "manager" = the manager rejected it. stage "final" = rejected or
// approved at final approval.

const body = $json.body ?? $json;
const src  = body.data ?? $json.data ?? $json;

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const decision   = src.decision ?? 'Updated';
const isApproved = decision.toLowerCase() === 'approved';
const stage      = src.stage ?? null;

const statusColor = isApproved ? '#11A8A0' : '#d33c1f';

const leaveType = esc(src.leaveType ?? 'Leave');
const fromDate  = esc(src.fromDate);
const toDate    = esc(src.toDate);
const dateRange = fromDate === toDate ? fromDate : `${fromDate} to ${toDate}`;
const days      = Number(src.days) || 0;
const daysLabel = `${days} ${days === 1 ? 'day' : 'days'}`;

const outcome = isApproved
  ? 'approved'
  : stage === 'manager'
    ? 'rejected by your manager'
    : stage === 'final'
      ? 'rejected at final approval'
      : decision.toLowerCase();

const payload = {
  requestId:     esc(src.requestId),
  employeeName:  esc(src.employeeName ?? 'there'),
  employeeEmail: src.employeeEmail ?? '',
  leaveType,
  fromDate,
  toDate,
  dateRange,
  days,
  daysLabel,
  decision:      esc(decision),
  statusColor,
  headline:      `Your ${leaveType} leave was ${outcome}`,
};

payload.subject = body.subject ?? `Your leave request was ${decision.toLowerCase()}`;
payload.to      = body.to ?? payload.employeeEmail;

if (!payload.to) {
  throw new Error(`leave.decision ${src.requestId}: missing employee email`);
}

return { json: payload };

// Aidapt ALMS · Build Remote Work Approval Email
// Event: remote_work.approval_request. Sent to the employee's manager.
// Approve and Reject use the backend decision links and work once.

const PROD_BASE = 'https://aidapt-alms-backend.onrender.com';
const DEV_BASE = 'http://localhost:4000';

const body = $json.body ?? $json;
const src = body.data ?? $json.data ?? $json;

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const fixUrl = (url) =>
  typeof url === 'string' ? url.replace(DEV_BASE, PROD_BASE) : '';

const employeeName = esc(src.employeeName || 'An employee');
const days = Number(src.days) || 0;
const daysLabel = days + ' ' + (days === 1 ? 'day' : 'days');

const payload = {
  requestId: esc(src.requestId),
  employeeName,
  fromDate: esc(src.fromDate),
  toDate: esc(src.toDate),
  days,
  daysLabel,
  reason: esc(src.reason) || 'No reason given',
  approveUrl: fixUrl(src.approveUrl),
  rejectUrl: fixUrl(src.rejectUrl),
  eyebrow: 'A request is waiting on your approval',
  headline: employeeName + ' requested remote work',
  stepNote: 'Without your approval, a remote check-in on these dates counts as absent.',
  approveLabel: 'Approve',
  tag: 'Remote Work',
};

payload.to = body.to ?? src.managerEmail ?? '';
payload.subject = body.subject
  ?? ('Remote work request from ' + (src.employeeName || 'an employee') + ' (' + (src.fromDate || '') + ')');

if (!payload.to) {
  throw new Error('remote_work.approval_request ' + src.requestId + ': missing recipient');
}
if (!payload.approveUrl || !payload.rejectUrl) {
  throw new Error('remote_work.approval_request ' + src.requestId + ': approve/reject URL missing');
}

return { json: payload };

// Aidapt ALMS · Build Remote Work Decision Email
// Event: remote_work.decision. Sent to the employee who applied.

const body = $json.body ?? $json;
const src = body.data ?? $json.data ?? $json;

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const decision = src.decision ?? 'Updated';
const isApproved = String(decision).toLowerCase() === 'approved';
const fromDate = esc(src.fromDate);
const toDate = esc(src.toDate);
const dateRange = fromDate === toDate ? fromDate : fromDate + ' to ' + toDate;
const days = Number(src.days) || 0;
const daysLabel = days + ' ' + (days === 1 ? 'day' : 'days');

const payload = {
  requestId: esc(src.requestId),
  employeeName: esc(src.employeeName ?? 'there'),
  employeeEmail: src.employeeEmail ?? '',
  fromDate,
  toDate,
  dateRange,
  days,
  daysLabel,
  decision: esc(decision),
  statusColor: isApproved ? '#11A8A0' : '#d33c1f',
  headline: 'Your remote work was ' + String(decision).toLowerCase(),
};

payload.subject = body.subject ?? ('Your remote work request was ' + String(decision).toLowerCase());
payload.to = body.to ?? payload.employeeEmail;

if (!payload.to) {
  throw new Error('remote_work.decision ' + src.requestId + ': missing employee email');
}

return { json: payload };
